                bin_counts[bisect_right(edges, values[t][i][j])] += 1
                uncertainty_sq_sum += uncertainty[t][i][j] ** 2

    count = sum(bin_counts)
    if count < min_count:
        return {
            "count": count,
            "bin_counts": bin_counts,
            "entropy": None,
            "uncertainty": None,
        }

    entropy = -sum(
        (bin_count / count) * math.log2(bin_count / count)
