        if bin_count > 0
    )
    return {
        "count": count,
        "bin_counts": bin_counts,
        "entropy": _round_output(entropy),
        "uncertainty": _round_output(math.sqrt(uncertainty_sq_sum) / count),
    }


def _weighted_histogram_window_region(
    values: list,
